"use strict";(globalThis.webpackChunkall_maker=globalThis.webpackChunkall_maker||[]).push([[8684],{7037(e){e.exports=JSON.parse('{"permalink":"/blog/docs-as-code-not-dev","source":"@site/blog/2026-03-19-dac-not-dev.md","title":"Docs-as-code is not development","description":"Using the same tools does not mean every project is the same.","date":"2026-03-19T00:00:00.000Z","tags":[{"inline":false,"label":"Technical writing","permalink":"/blog/tags/technical-writing"},{"inline":false,"label":"Opinion","permalink":"/blog/tags/opinion"}],"readingTime":3.25,"hasTruncateMarker":true,"authors":[{"name":"Strahinja Milo\u0161evi\u0107","title":"Senior Technical Writer","url":"https://strahinjamilosevic.github.io/","page":{"permalink":"/blog/authors/strahinja"},"socials":{"linkedin":"https://www.linkedin.com/in/strahinjamilosevic/","github":"https://github.com/strahinjamilosevic"},"description":"Hi, I\'m Stra. A long time ago I studied English language and literature. I don\'t know if I see myself as a linguist, but studying language and literature has definitely shaped how I view the world.\\n\\nThere\'s a plethora of things that interest me. I think what defines me is that I just get up and try them out. \\"Jack of all trades, master of none...\\" kind of deal, yes.\\n\\nWhat do I see myself as? I don\'t know. I\'d probably say a dedicated father and husband. An avid music enjoyer, a disentangler of topics, and a vain old fart. ;)\\n\\nBut that\'s the point of the old saying: \\"...oftentimes better than a master of one.\\" In any case, definitely \u2014 a maker of sorts.\\n","imageURL":"/img/prof.jpg","key":"strahinja"}],"frontMatter":{"slug":"docs-as-code-not-dev","title":"Docs-as-code is not development","authors":["strahinja"],"tags":["technical writing","opinion"],"description":"Using the same tools does not mean every project is the same."},"unlisted":false,"prevItem":{"title":"Forget cheat sheets, work with people","permalink":"/blog/cheat-sheets"},"nextItem":{"title":"Why all-maker","permalink":"/blog/all-maker"}}')},8453(e,t,n){n.d(t,{R:()=>i,x:()=>r});var a=n(6540);const o={},s=a.createContext(o);function i(e){const t=a.useContext(s);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:i(e.components),a.createElement(s.Provider,{value:t},e.children)}},9466(e,t,n){n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>r,default:()=>d,frontMatter:()=>i,metadata:()=>a,toc:()=>l});var a=n(7037),o=n(4848),s=n(8453);const i={slug:"docs-as-code-not-dev",title:"Docs-as-code is not development",authors:["strahinja"],tags:["technical writing","opinion"],description:"Using the same tools does not mean every project is the same."},r=void 0,h={authorsImageUrls:[void 0]},l=[];function c(e){const t={a:"a",em:"em",p:"p",...(0,s.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.p,{children:"Working with developers in a docs-as-code environment can lead to some undesired and time-wasteful consequences."}),"\n",(0,o.jsx)(t.p,{children:"You author in IDEs, use version control, create elaborate pipelines and automated workflows, and maintain the tooling. Then during SME reviews or stakeholder alignment you frequently end up defending arbitrary engineering decisions of your tooling stack instead of reviewing the content."}),"\n",(0,o.jsx)(t.p,{children:"The users of my API reference do not care if I had a neat commit message or a ticket number. Or if the pipeline passed all twenty Wiz checks introduced by the infra team. Checks that check everything in my repo but have nothing to check since I do not touch production code. Or use the same stack."}),"\n",(0,o.jsxs)(t.p,{children:["The users care about usability. About getting to the correct, helpful data in a way optimized for ",(0,o.jsx)(t.em,{children:"them"}),"."]}),"\n",(0,o.jsx)(t.p,{children:"Programmers overengineer simple concepts. It's natural. There is no off-switch for the way someone thinks. That is why conversations take a side-turn towards what interests, or bothers, their inquisitive, spectacular design mind."}),"\n",(0,o.jsxs)(t.p,{children:["The same way product managers ask for a specific type of content in a specific place of the website. They already know what ",(0,o.jsx)(t.em,{children:"they"})," want. But they provide very high-level context of how the feature is supposed to work. No technical specificities, or what the users will experience. And I get it\u2014it's not their job to develop it, but to design the product with the most business value and align everybody on where we are supposed to go."]}),"\n",(0,o.jsx)(t.p,{children:"However, the scrutiny your docs are put under needs to be directed. Reviews and feedback are great. But the lens needs to change. The standards cannot be the same for every repository, application, or product."}),"\n",(0,o.jsx)(t.p,{children:"So what do we do?"}),"\n",(0,o.jsx)(t.p,{children:"As technical writers, we get to the gist of it. Analyse it all. Distill the essence and pass it on to the users in plain language and intuitive testing resources. We all know this."}),"\n",(0,o.jsx)(t.p,{children:"The challenge is to manage expectations from the team as well as users. Because dealing with your team is as important as dealing with the users."}),"\n",(0,o.jsx)(t.p,{children:"Educate the team. Do not condescend but actually explain. This requires changing their perspective and is genuinely hard to do. You are meant to do what good leaders and product managers do weekly\u2014make sure everybody is on the same page and understands each other. Be clear, in an empathetic, helpful way, about your purpose, approach, what the benefit for the user is, and how you get there from the chaotic amalgamation of tickets, PRs, and meeting notes."}),"\n",(0,o.jsxs)(t.p,{children:["This is why certain very successful technical writers transition into leadership roles. Not because of the natural progression of the ",(0,o.jsx)(t.a,{href:"/blog/career",children:"career ladder"}),". It's because they realize the benefits of being successful in getting everybody to work together towards the same goal with a clearly understood plan and deliverables. This is the point. The very skill that will steer that conversation where it needs to go, not discuss why this SSG choice over the latest FE, CMS wonder, but get to the essence that the users need."]}),"\n",(0,o.jsx)(t.p,{children:"You might have already experienced this\u2014being asked about advancement and then offered owning a project that seemingly does not really fit with your current IC job. That was the leadership vetting you. Testing whether you'd be able to align everybody and make them productive on a smaller-scale project."}),"\n",(0,o.jsx)(t.p,{children:"Whether you want that job or not is another topic. But the skill to get you there is the same, and worth investing time in. Learn how to manage expectations, make everybody understand each other, and work towards the same goal productively. That's it. Sounds simpler than it actually is though."}),"\n",(0,o.jsx)(t.p,{children:"The trick is to do it on a smaller scale. You'll have an easier time the next go around. Iteratively. And on a scale of years, not quarters, the benefits will be palpable."})]})}function d(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(c,{...e})}):c(e)}}}]);